<script setup lang="ts">
import { discoveryStatus } from '../../../../../utils/page-error'
definePageMeta({ key: route => route.path })
const route = useRoute()
const { t, locale, localPath, labelTag, number, countLabel } = useWebLocale()
const api = useDiscovery()
const theme = String(route.params.theme)
const topic = String(route.params.topic)
const { data, error, status, refresh } = await useAsyncData(`topic:${locale.value}:${theme}:${topic}`, () => api.topic(theme, topic), { getCachedData: (key, app) => app.isHydrating ? app.payload.data[key] : undefined })
if (error.value && import.meta.server) throw createError({ statusCode: discoveryStatus(error.value), statusMessage: discoveryStatus(error.value) === 404 ? 'Topic not found' : 'Discovery unavailable' })
const levelKeys = ['easy', 'normal', 'hard', 'hardcore'] as const
const levelDescriptions = ['easyDescription', 'normalDescription', 'hardDescription', 'hardcoreDescription'] as const
usePageSeo(() => data.value?.topic.label ?? t('topics'), () => data.value?.topic.description || t('levelDescription'), () => data.value?.topic.playable ?? false)
</script>
<template><div class="page-shell detail-page"><nav class="breadcrumbs" :aria-label="t('discover')"><NuxtLink :to="localPath('/')">QuickQuiz</NuxtLink><span>/</span><NuxtLink :to="localPath(`/themes/${encodeURIComponent(theme)}`)">{{ data?.topic.theme.name ?? t('theme') }}</NuxtLink><template v-if="data"><span>/</span><span>{{ data.topic.label }}</span></template></nav><DiscoveryState v-if="error" state="error" @retry="refresh()" /><DiscoveryState v-else-if="status === 'pending'" state="loading" /><template v-else-if="data"><header class="detail-hero"><div><p class="eyebrow">{{ data.topic.theme.name }} · {{ t('topicEyebrow') }}</p><h1>{{ data.topic.label }}</h1><p class="detail-description">{{ data.topic.description || t('levelDescription') }}</p></div><div class="detail-stat"><strong>{{ number(data.topic.questionCount) }}</strong><span>{{ countLabel(data.topic.questionCount, 'questions') }}</span><small>{{ data.topic.playable ? t('ready') : t('comingSoon') }}</small></div></header><section v-if="data.topic.playable" class="level-section"><div class="section-heading"><div><h2>{{ t('chooseLevel') }}</h2><p>{{ t('levelDescription') }}</p></div></div><div class="level-grid"><NuxtLink v-for="level in data.topic.difficulties" :key="level.id" :to="{ path: localPath('/play'), query: { theme, topic, difficulty: level.id } }" class="level-card"><span class="level-number">0{{ level.id }}</span><h3>{{ t(levelKeys[level.id - 1]!) }}</h3><p>{{ t(levelDescriptions[level.id - 1]!) }}</p><span class="level-footer">{{ number(level.questionCount) }} {{ countLabel(level.questionCount, 'questions') }}<UIcon name="i-lucide-arrow-right" /></span></NuxtLink></div></section><DiscoveryState v-else state="empty" /><section v-if="data.topic.tags.length" class="related-section"><div><p class="eyebrow">{{ t('related') }}</p><h2>{{ t('relatedDescription') }}</h2></div><div class="area-chips"><NuxtLink v-for="tag in data.topic.tags" :key="tag" :to="{ path: localPath('/explore'), query: { kind: 'topics', topicTag: tag } }" class="area-chip">{{ labelTag(tag) }}<UIcon name="i-lucide-arrow-up-right" /></NuxtLink></div></section></template></div></template>
